text:
      aReason = NS_ConvertASCIItoUTF16(errorName);
    }
  }
}

// Verifies an already-loaded self cert locally for the given usage. On failure
// it clears aSelfCert and records the reason; only failure to read the cert
// bytes is reported as an error.
static nsresult VerifySelfCert(CertVerifier* aCertVerifier,
                               mozilla::psm::VerifyUsage aUsage,
                               nsCOMPtr<nsIX509Cert>& aSelfCert,
                               nsAString& aErrorReason) {
  nsTArray<uint8_t> certBytes;
  nsresult rv = aSelfCert->GetRawDER(certBytes);
  NS_ENSURE_SUCCESS(rv, rv);

  mozilla::pkix::Result result = nsCMSSecureMessage::VerifyEmailUsageLocalOnly(
      aCertVerifier, certBytes, aUsage);
  if (result != mozilla::pkix::Success) {
    GetCertVerificationErrorReason(result, aErrorReason);
    aSelfCert = nullptr;
  }
  return NS_OK;
}

/* Used to figure out what certs should be used when encrypting this message.
 */
nsresult nsMsgComposeSecure::MimeCryptoHackCerts(const nsACString& aRecipients,
                                                 nsIMsgSendReport* sendReport,
                                                 bool aEncrypt, bool aSign,
                                                 nsIMsgIdentity* aIdentity) {
  nsCOMPtr<nsIX509CertDB> certdb =
      mozilla::components::NSSCertificateDB::Service();
  nsresult res = NS_OK;
  nsAutoString selfSigningCertErrorReason;
  nsAutoString selfEncryptionCertErrorReason;

  PR_ASSERT(aEncrypt || aSign);

  /*
   Signing and encryption certs use the following (per-identity) preferences:
   - "signing_cert_name"/"encryption_cert_name": a string specifying the
     nickname of the certificate
   - "signing_cert_dbkey"/"encryption_cert_dbkey": a Base64 encoded blob
     specifying an nsIX509Cert dbKey (represents serial number
     and issuer DN, which is considered to be unique for X.509 certificates)
  */

  RefPtr<SharedCertVerifier> certVerifier(GetDefaultCertVerifier());
  NS_ENSURE_TRUE(certVerifier, NS_ERROR_UNEXPECTED);

  // Calling CERT_GetCertNicknames has the desired side effect of
  // traversing all tokens, and bringing up prompts to unlock them.
  CERTCertNicknames* result_unused = CERT_GetCertNicknames(
      CERT_GetDefaultCertDB(), SEC_CERT_NICKNAMES_USER, nullptr);
  CERT_FreeNicknames(result_unused);

  if (!mEncryptionCertDBKey.IsEmpty()) {
    res = certdb->FindCertByDBKey(mEncryptionCertDBKey,
                                  getter_AddRefs(mSelfEncryptionCert));
    if (NS_SUCCEEDED(res) && mSelfEncryptionCert) {
      res = VerifySelfCert(certVerifier,
                           mozilla::psm::VerifyUsage::EmailRecipient,
                           mSelfEncryptionCert, selfEncryptionCertErrorReason);
      NS_ENSURE_SUCCESS(res, res);
    }
  }

  // same procedure for the signing cert
  if (!mSigningCertDBKey.IsEmpty()) {
    res = certdb->FindCertByDBKey(mSigningCertDBKey,
                                  getter_AddRefs(mSelfSigningCert));
    if (NS_SUCCEEDED(res) && mSelfSigningCert) {
      res = VerifySelfCert(certVerifier, mozilla::psm::VerifyUsage::EmailSigner,
                           mSelfSigningCert, selfSigningCertErrorReason);
      NS_ENSURE_SUCCESS(res, res);
    }
  }

  // must have both the signing and encryption certs to sign
  if (!mSelfSigningCert && aSign) {
    nsAutoCString errorReason =
        NS_ConvertUTF16toUTF8(selfSigningCertErrorReason);
    SetErrorWithParam(sendReport, "SenderSigningCertInvalid",
                      errorReason.get());
    return NS_ERROR_FAILURE;
  }

  if (!mSelfEncryptionCert && aEncrypt) {
    nsAutoCString errorReason =
        NS_ConvertUTF16toUTF8(selfEncryptionCertErrorReason);
    SetErrorWithParam(sendReport, "SenderEncryptionCertInvalid",
                      errorReason.get());
    return NS_ERROR_FAILURE;
  }

  if (aEncrypt && mSelfEncryptionCert) {
    // Make sure self's configured cert is prepared for being used
    // as an email recipient cert.
    UniqueCERTCertificate nsscert(mSelfEncryptionCert->GetCert());
    if (!nsscert) {
